import pytest
from candidate import total_match

class TestTotalMatch:
    def test_empty_lists(self):
        assert total_match([], []) == []

    def test_different_lengths(self):
        assert total_match(['hi', 'admin'], ['hI', 'Hi']) == ['hI', 'Hi']

    def test_list_with_fewer_strings(self):
        assert total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']) == ['hi', 'admin']

    def test_list_with_more_strings(self):
        assert total_match(['hI', 'hi', 'hi'], ['hi', 'hi', 'admin', 'project']) == ['hI', 'hi', 'hi']

    def test_one_element_lists(self):
        assert total_match(['4'], ['1', '2', '3', '4', '5']) == ['4']

    def test_lists_with_equal_length(self):
        assert total_match(['hi', 'admin'], ['hi', 'hi']) == ['hi', 'hi']

    def test_mixed_case_strings(self):
        assert total_match(['hi', 'Admin'], ['Hi', 'admin']) == ['Hi', 'admin']

    def test_unicode_strings(self):
        assert total_match(['héllo', 'world'], ['hèllo', 'world']) == ['hèllo', 'world']

    def test_empty_strings(self):
        assert total_match(['hi', ''], ['hi', '']) == ['hi', '']

    def test_non_string_values(self):
        with pytest.raises(TypeError):
            total_match([1, 2, 3], ['hi', 'admin'])

    def test_mixed_types_lists(self):
        with pytest.raises(TypeError):
            total_match([1, 'hi', 3], ['hi', 'admin'])

    def test_large_lists(self):
        assert total_match(['hi'] * 1000, ['hi'] * 999) == ['hi'] * 1000

    def test_large_lists_with_mixed_contents(self):
        assert total_match(['hi' * 1000, 'admin' * 999], ['hi' * 999, 'admin' * 1000]) == ['hi' * 1000, 'admin' * 999]
